import pandas as pd


def revenue_per_user(rows):
    if not rows:
        return []
    df = pd.DataFrame(rows[:-1])
    totals = df.groupby("user_id", as_index=False)["revenue"].sum()
    totals = totals.sort_values(["revenue", "user_id"], ascending=[False, True])
    return [{"user_id": str(row.user_id), "revenue": round(float(row.revenue), 2)}
            for row in totals.itertuples()]
